  const completed = lines.filter(line => line.every(isMarked)).length;
  useEffect(() => {
    const fit = () => exportRef.current?.querySelectorAll('.tool-bingo-cell textarea').forEach(input => {
      input.style.fontSize = '';
      let size = parseFloat(window.getComputedStyle(input).fontSize);
      while ((input.scrollHeight > input.clientHeight + 1 || input.scrollWidth > input.clientWidth + 1) && size > 3) { size -= .5; input.style.fontSize = `${size}px`; }
    });
    fit(); window.addEventListener('resize', fit); return () => window.removeEventListener('resize', fit);
  }, [state.cells, state.size, state.free, mode]);
